arguments.command:
set -euo pipefail; export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; D=.claude/skills/agent-emulator-debugging/scripts/drive.py;

TRACK1=/opt/nothingness/media/01-undercover-49.opus;
TRACK2=/opt/nothingness/media/02-undercover-50.opus;

echo '--- state before'; D inspect | python -c "import sys,json; d=json.load(sys.stdin); print('isPlaying',d['playback']['isPlaying'],'currentIndex',d['playback']['currentIndex'],'title', (d['playback']['songInfo'] or {}).get('title'))";

echo '--- pause'; D pause >/dev/null; OUT=$(D inspect); python - <<'PY'
import json,sys,os
s=os.environ['OUT']
d=json.loads(s)
print('pause:isPlaying',d['playback']['isPlaying'])
PY

